 records[key]={'key':key,'sec':sec,'stem':'<p>'+stem+'</p>','options':[{'k':chr(65+i),'html':o} for i,o in enumerate(options)],'answer':list(answer),'why':why,'reference':DOC+doc,'correction':note,'oos':False}
