occ={}
for n,keys in maps.items():
 for p,k in enumerate(keys,1):occ.setdefault(k,[]).append({'pdf':n,'page':p})
questions=[];audit=[];seen=set()
for n,keys in maps.items():
 for p,k in enumerate(keys,1):
  if k in seen:
   audit.append({'pdf':n,'page':p,'key':k,'status':'duplicate','canonical':occ[k][0]});continue
  seen.add(k)
  if k in excluded:
   audit.append({'pdf':n,'page':p,'key':k,'status':'excluded','reason':excluded[k]});continue
  q=records[k];q['uid']='lq-'+k;q['n']=len(questions)+1;q['label']=f'LeetQuiz #{q["n"]} · '+{'P':'Platform','I':'Ingestion','T':'Transformation','J':'Lakeflow Jobs','C':'CI/CD','O':'Optimization','G':'Governance'}[q['sec']]
  q['sources']=occ[k];q['origin_pdf']=n;q['sourcePage']=p
  q['explain']='<p class="ans">✅ সঠিক উত্তর: '+', '.join(q['answer'])+'</p><h3>ব্যাখ্যা</h3><p>'+q.pop('why')+'</p>'
  if q['correction']:q['explain']+='<p><strong>Source correction:</strong> '+q['correction']+'</p>'
  q['explain']+='<h3>তথ্যসূত্র</h3><p><a href="'+q['reference']+'" target="_blank" rel="noopener noreferrer">Databricks documentation</a></p>'
  questions.append(q);audit.append({'pdf':n,'page':p,'key':k,'status':'kept','uid':q['uid'],'section':q['sec'],'correction':q['correction']})
Path(ROOT/'leetquiz/refined-questions.json').write_text(json.dumps(questions,ensure_ascii=False,indent=2))
Path(ROOT/'leetquiz/refinement-audit.json').write_text(json.dumps({'guide':GUIDE,'source_pages':158,'unique_questions':len(seen),'kept':len(questions),'excluded_unique':len(excluded),'duplicate_pages':sum(x['status']=='duplicate' for x in audit),'note':'Syllabus exclusions are study-priority judgments against explicit May 2026 objectives, not an official excluded-question list. Cosmetic renames are yellow; substantive corrections are disclosed separately.','pages':audit},ensure_ascii=False,indent=2))
print('Retained',len(questions),'Unique',len(seen),'Duplicates',sum(x['status']=='duplicate' for x in audit),'Excluded',sum(x['status']=='excluded' for x in audit))
